query Premerge($pr: Int!, $head: String!) {
  repository(owner: "Jacob-J-Thomas", name: "GraphGoblin") {
    ref(qualifiedName: "refs/heads/main") { target { oid } }
    pullRequest(number: $pr) {
      number
      isDraft
      state
      baseRefName
      baseRefOid
      headRefOid
      mergeable
      mergeStateStatus
      potentialMergeCommit { ...CommitState }
      closingIssuesReferences(first: 100) {
        nodes { ...IssueState }
        pageInfo { hasNextPage hasPreviousPage }
      }
      reviewThreads(first: 100) {
        nodes { isResolved isOutdated }
        pageInfo { hasNextPage hasPreviousPage }
      }
      reviews(first: 100) {
        nodes { state author { login } }
        pageInfo { hasNextPage hasPreviousPage }
      }
    }
    head: object(expression: $head) { ...CommitState }
    issue416: issue(number: 416) { ...IssueState }
issue420: issue(number: 420) { ...IssueState }
issue448: issue(number: 448) { ...IssueState }
issue459: issue(number: 459) { ...IssueState }
  }
}

fragment IssueState on Issue {
  number
  state
  repository { nameWithOwner }
  labels(first: 100) {
    nodes { name }
    pageInfo { hasNextPage hasPreviousPage }
  }
}

fragment CommitState on Commit {
  oid
  tree { oid }
  statusCheckRollup {
    state
    contexts(first: 100) {
      totalCount
      pageInfo { hasNextPage hasPreviousPage }
      nodes {
        __typename
        ... on CheckRun { name status conclusion }
        ... on StatusContext { context state }
      }
    }
  }
}
